	local embeddedAssetCache = {}
	local function getEmbeddedPngAsset(base64, path, name)
		if base64 == nil or base64 == "" then
			return nil
		end
		if embeddedAssetCache[path] ~= nil then
			return embeddedAssetCache[path]
		end
		local getGlobal = runtime.fn
		local isFile = getGlobal("isfile")
		local writeFile = getGlobal("writefile")
		local makeFolder = getGlobal("makefolder")
		local isFolder = getGlobal("isfolder")
		local getCustomAsset = getGlobal("getcustomasset") or getGlobal("getsynasset")
		assert(type(isFile) == "function" and type(writeFile) == "function"
			and type(getCustomAsset) == "function",
			string.format("%s requires isfile, writefile, and getcustomasset/getsynasset.", name))
		local fileCheckOk, fileExists = pcall(isFile, path)
		assert(fileCheckOk, string.format("Failed to check %s cache file: %s", name, tostring(fileExists)))
		if not fileExists then
			if type(makeFolder) == "function" then
				for _, folder in { "GHP_scripts", "GHP_scripts/ui-library-cache" } do
					local folderExists = false
					if type(isFolder) == "function" then
						local folderCheckOk, exists = pcall(isFolder, folder)
						assert(folderCheckOk,
							string.format("Failed to check %s cache folder: %s", name, tostring(exists)))
						folderExists = exists
					end
					if not folderExists then
						local folderCreated, createError = pcall(makeFolder, folder)
						if not folderCreated and type(isFolder) == "function" then
							local folderCheckOk, exists = pcall(isFolder, folder)
							assert(folderCheckOk and exists,
								string.format("Failed to create %s cache folder: %s", name, tostring(createError)))
						end
					end
				end
			end
			local decoded = HttpService:Base64Decode(base64:gsub("%s", ""))
			local wrote, writeError = pcall(writeFile, path, decoded)
			assert(wrote, string.format("Failed to cache %s: %s", name, tostring(writeError)))
		end
		local resolved, asset = pcall(getCustomAsset, path)
		assert(resolved and type(asset) == "string",
			string.format("Failed to load cached %s: %s", name, tostring(asset)))
		embeddedAssetCache[path] = asset
		return asset
	end
	local function getLucideAtlasAsset()
		return getEmbeddedPngAsset(
