	local function setImageSource(image, source)
		local iconName = type(source) == "string" and source:match("^lucide:([%w%-]+)$") or nil
		if iconName ~= nil then
			local index = LUCIDE_ICON_INDEX[iconName]
			assert(index ~= nil, string.format("Unknown Lucide icon '%s'.", iconName))
			image.Image = getLucideAtlasAsset()
			image.ImageRectOffset = Vector2.new((index % 8) * 32, math.floor(index / 8) * 32)
			image.ImageRectSize = Vector2.new(32, 32)
			image.ScaleType = Enum.ScaleType.Fit
			return true
		end
		image.Image = source or ""
		image.ImageRectOffset = Vector2.zero
		image.ImageRectSize = Vector2.zero
		return false
	end
